mapper.select:
SELECT om.order_main_id, om.order_no, om.create_time, om.order_thumbnail, om.pick_address, om.deliver_address, om.total_amount, om.order_status, om.order_type, mb.merchant_base_id as merchant_id, mb.merchant_name, mb.logo as merchant_logo, mb.rating as merchant_rating, mb. phone as merchant_phone, ub.username, ub.nickname as user_nickname FROM order_main om INNER JOIN order_delivery od ON om.order_main_id = od.order_main_id LEFT JOIN merchant_base mb ON om.merchant_id = mb.merchant_base_id LEFT JOIN user_base ub ON om. user_id = ub.user_base_id
od.rider_id = #{riderId}
AND om.create_time >= DATE_FORMAT(CURDATE(), '%Y-%m-%d 00:00:00') AND om.create_time <= NOW()
AND om.create_time >= DATE_SUB(CURDATE(), INTERVAL 1 DAY) AND om.create_time < DATE_FORMAT(CURDATE(), '%Y-%m-%d 00:00:00')
AND om.create_time >= DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) AND om.create_time <= NOW()
AND om.create_time >= DATE_FORMAT(CURDATE(), '%Y-%m-01 00:00:00') AND om.create_time <= NOW()
AND om.order_status = #{orderMain.orderStatus}
AND om.order_no LIKE CONCAT('%', #{orderMain.orderNo}, '%')
AND om.order_type = #{orderMain.orderType}
AND om.pay_status = #{orderMain.payStatus}
ORDER BY om.create_time DESC
